package com.madlava.runtime;
import static org.junit.jupiter.api.Assertions.*; import com.madlava.core.FeatureRegistry; import java.lang.instrument.Instrumentation; import java.lang.reflect.Proxy; import java.nio.file.Path; import java.time.Clock; import org.junit.jupiter.api.Test;
class RuntimeContextTest { @Test void normalizesOutputAndRequiresServices(){Instrumentation i=(Instrumentation)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Instrumentation.class},(p,m,a)->null);RuntimeContext c=new RuntimeContext(i,Clock.systemUTC(),Path.of("target","..","target","reports"),new FeatureRegistry());assertTrue(c.outputDirectory().isAbsolute());assertTrue(c.outputDirectory().endsWith(Path.of("target","reports")));assertThrows(NullPointerException.class,()->new RuntimeContext(null,Clock.systemUTC(),Path.of("x"),new FeatureRegistry()));}}
